def L(a):return S.latex(S.simplify(a))
def m(a):return '$'+L(a)+'$'
def num(a,n=3):
 value=float(a); result=f'{value:.{n}g}'
 if 'e' in result:
  mant,exp=f'{value:.{n-1}e}'.split('e');return mant+chr(92)+'times10^{'+str(int(exp))+'}'
 return result
def step(code,text):return {'code':code,'text':text}
