def add(n,title,stem,parts,calc=False,sub='Integration',notes='',diagram=None):
 ps=[a[0] for a in parts];ms=[a[1] for a in parts]
 for pa,ma in zip(ps,ms):
  assert sum(int(s['code'][1:]) if s['code']!='AG' else 0 for s in ma['steps'])==pa['marks'],(n,pa,ma)
 q={'id':rf'ib-aa-c2-{n:03d}','subject':'math-aa-hl','topicId':'calculus','collectionId':'calculus-2','number':n,'title':title,'subtopic':sub,'difficulty':SRC[n-1]['difficulty'],'calculator':calc,'marks':sum(z['marks'] for z in ps),'stem':re.sub(re.escape(chr(92)+'n')+r'(?![A-Za-z])',chr(10),stem),'parts':ps,'markScheme':ms,'source':{'document':'IB Mathematics AA HL Questionbank - Calculus II.pdf','question':n},'verification':{'method':'symbolic/numerical/reasoned','notes':notes or 'Worked solution recomputed for the new values; mark totals checked.'},'status':'published'}
 if len(ps)==1 and ps[0]['label']=='':q['stem']+=' '+ps[0]['prompt'];q['parts']=[]
 if diagram:q['diagramSvg']=diagram
