def antiderivative(f,z=x):
 F=S.integrate(f,z);assert not F.has(S.Integral),f
 assert S.simplify(S.diff(F,z)-f)==0,(f,F)
 checks.append('primitive:'+str(f));return F

def initial(n,f,a,b):
 F=antiderivative(f);c=S.simplify(b-F.subs(x,a));ans=S.simplify(F+c)
 assert S.simplify(ans.subs(x,a)-b)==0
 add(n,'Recovering a function',rf"A function $f$ satisfies $f'(x)={L(f)}$ and $f({L(a)})={L(b)}$.",[p('', 'Find $f(x)$.',6,('M1','Integrate the derivative, including an arbitrary constant.'),('A2',rf'$f(x)={L(F)}+C$.'),('M1',rf'Substitute the point: ${L(b)}={L(F.subs(x,a))}+C$.'),('A1',rf'$C={L(c)}$.'),('A1',rf'$f(x)={L(ans)}$.'))],notes='SymPy differentiated the answer and substituted the initial point.')

def roots(f,a,b,z=t):
 fn=S.lambdify(z,f,'numpy');grid=np.linspace(float(a),float(b),2001);rr=[]
 for lo,hi in zip(grid[:-1],grid[1:]):
  fl,fh=fn(lo),fn(hi)
  if np.isfinite(fl) and abs(fl)<1e-9:rr.append(lo)
  if np.isfinite(fl) and np.isfinite(fh) and fl*fh<0:rr.append(brentq(fn,lo,hi))
 if abs(fn(float(b)))<1e-9:rr.append(float(b))
 ordered=sorted(min(max(float(r),float(a)),float(b)) for r in rr);unique=[]
 for r in ordered:
  if not unique or abs(r-unique[-1])>1e-8:unique.append(r)
 return unique
def integ(f,a,b,z=t):
 fn=S.lambdify(z,f,'numpy');return quad(fn,float(a),float(b),epsabs=1e-10)[0]
def dist(v,a,b):
 rr=[a]+[r for r in roots(v,a,b) if a<r<b]+[b];return sum(abs(integ(v,lo,hi)) for lo,hi in zip(rr[:-1],rr[1:]))
def graph(f,a,b,z=x,yl=None,title='Graph',labels=None,shade=None):
 fn=S.lambdify(z,f,'numpy');xs=np.linspace(float(a),float(b),300);ys=np.asarray(fn(xs))+np.zeros_like(xs)
 finite=ys[np.isfinite(ys)];mi,ma=yl or (min(0,float(finite.min())),max(0,float(finite.max())));pad=max((ma-mi)*.12,.5);mi-=pad;ma+=pad
 X=lambda v:52+(float(v)-float(a))/(float(b)-float(a))*496
 Y=lambda v:292-(float(v)-mi)/(ma-mi)*244
 pts=' '.join(rf'{X(u):.2f},{Y(v):.2f}' for u,v in zip(xs,ys) if np.isfinite(v) and mi<=v<=ma)
 svg=rf'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 350" role="img"><title>{title}</title><rect x="0" y="0" width="600" height="350" fill="white"/><line x1="52" y1="{Y(0):.2f}" x2="554" y2="{Y(0):.2f}" stroke="#555"/><polyline points="{pts}" fill="none" stroke="#7a1f24" stroke-width="2.5"/>'
 if a<=0<=b:svg+=rf'<line x1="{X(0):.2f}" y1="40" x2="{X(0):.2f}" y2="300" stroke="#555"/>'
 if shade:
  sa,sb=shade;shade_x=np.linspace(float(sa),float(sb),160)
  polygon=f'{X(sa):.2f},{Y(0):.2f} '+' '.join(f'{X(u):.2f},{Y(fn(u)):.2f}' for u in shade_x)+f' {X(sb):.2f},{Y(0):.2f}'
  svg+=f'<polygon points="{polygon}" fill="#f3dadd" fill-opacity="0.6"/><text x="{X((sa+sb)/2):.2f}" y="{Y(float(fn((sa+sb)/2))/2):.2f}" text-anchor="middle" fill="#7a1f24" font-size="17">R</text>'
 def ticks(lo,hi):
  raw=(hi-lo)/4; power=10**math.floor(math.log10(raw));step=min([1,2,5,10],key=lambda k:abs(k*power-raw))*power
  return np.arange(math.ceil(lo/step)*step,hi+step*0.001,step)
 for val in ticks(float(a),float(b)):svg+=rf'<text x="{X(val):.2f}" y="325" text-anchor="middle" font-size="13">{val:.3g}</text>'
 for val in ticks(mi+pad,ma-pad):svg+=rf'<text x="43" y="{Y(val):.2f}" text-anchor="end" font-size="12">{val:.3g}</text>'
 if labels:
  for lx,ly,label in labels:
   svg+=f'<circle cx="{X(lx):.2f}" cy="{Y(ly):.2f}" r="3.5" fill="#7a1f24"/><text x="{X(lx)+7:.2f}" y="{Y(ly)-10:.2f}" font-size="14" fill="#222">{label}</text>'
 return svg+'<text x="560" y="325" font-size="14">'+str(z)+'</text></svg>' 

