add(96,'The largest area under an exponential',r'Let $f(x)=3e^{x/4}$ and $g(x)=mx$, $m>0$. If they meet, let R be the region bounded by the $y$-axis and the curves up to their first positive intersection.',[p('a','For $m=3$, sketch the curves and find the area of R.',7,('A1','$f(0)=3$ and $g(0)=0$.'),('A1','Exponential convex upward; line slope $3$.'),('M1','Solve $3e^{x/4}=3x$ for the first positive root.'),('A1',rf'$r={num(rr[0])}$.'),('M1',r'$A=\int_0^r(3e^{x/4}-3x)dx$.'),('A1',r'Primitive $12e^{x/4}-3x^2/2$.'),('A1',rf'$A={num(ar)}$.')),p('b','Find the value of $m$ producing the greatest area of R, and find that area.',8,('M1','At an intersection $r$, $m=3e^{r/4}/r$.'),('A1',r'For the first intersection, $0<r\le4$.'),('M1','Express the area using $r$.'),('A1','$A(r)=12(e^{r/4}-1)-(3r/2)e^{r/4}$.'),('M1',r'Differentiate: $A\prime=(3/8)e^{r/4}(4-r)$.'),('R1','It is positive for $0<r<4$, so the maximum occurs at tangency $r=4$.'),('A1',r'$m=3e/4$.'),('A1',rf'$A_{{max}}={L(amax)}$.'))],True)
add(97,'An inverse cosine integral',r'Find $\int\arccos(2x)dx$, for $|x|<1/2$.',[p('','',5,('M1',r'$u=\arccos(2x)$, $dv=dx$.'),('A1',r'$du=-2dx/\sqrt{1-4x^2}$, $v=x$.'),('M1',r'Integral $=x\arccos(2x)+\int2x/\sqrt{1-4x^2}dx$.'),('A1',r'The remaining integral is $-\tfrac12\sqrt{1-4x^2}$.'),('A1',r'$x\arccos(2x)-\tfrac12\sqrt{1-4x^2}+C$.'))],sub='Integration by parts')
f=S.exp(-2*x)*S.sin(2*x)-2*x+4*x*x;series=S.series(f,x,0,6)
add(98,'Cancellation in a Maclaurin series',r'Let $f(x)=e^{-2x}\sin2x-2x+4x^2$. By differentiating, find its first non-zero Maclaurin term.',[p('','',7,('A1','$f(0)=0$.'),('M1','Differentiate the exponential-trigonometric product.'),('A1',r'$f\prime(0)=0$.'),('A1',r'$f\prime\prime(0)=0$.'),('M1','Continue to the third derivative.'),('A1',rf'$f^{{(3)}}(0)={L(S.diff(f,x,3).subs(x,0))}$.'),('A1',rf'First non-zero term ${L(S.diff(f,x,3).subs(x,0)*x**3/6)}$.'))],sub='Maclaurin series',notes='Symbolic Taylor derivatives and the expanded series agree.')
add(99,'Completing the square after substitution',r'Using $u=e^x-3$, find $\int\dfrac{e^x}{e^{2x}-6e^x+13}dx$.',[p('','',6,('M1','$du=e^x dx$.'),('A1','Denominator $=(e^x-3)^2+4=u^2+4$.'),('M1',r'The integral becomes $\int du/(u^2+4)$.'),('A1',r'Use the arctangent standard integral.'),('A1',r'$\tfrac12\arctan(u/2)+C$.'),('A1',r'$\tfrac12\arctan((e^x-3)/2)+C$.'))],sub='Integration by substitution')
save()
# 100-123: individual advanced differential equations, series and integrals.
add(100,'A separable rational equation',r'Solve $(1+x^2)y\prime=1+y^2$, given $y(0)=2$. State the maximal interval of the solution containing $0$.',[p('','',6,('M1',r'$dy/(1+y^2)=dx/(1+x^2)$.'),('A1',r'$\arctan y=\arctan x+C$.'),('M1',r'$C=\arctan2$ from the initial condition.'),('M1','Use the tangent addition formula.'),('A1',r'$y=(x+2)/(1-2x)$.'),('A1',r'$-\infty<x<1/2$; the denominator vanishes at $x=1/2$.'))],sub='Differential equations')
f=(x**3/3+3*x*x/2+3)/(x+3);mini=roots(S.diff(f,x),0,1,x)[0]
add(101,'Euler approximation and concavity',r'For $x>-3$, $y\prime+y/(x+3)=x$ and $y(0)=1$.',[p('a','Use Euler’s method with step $0.5$ to estimate $y(1)$.',3,('M1','$y_{n+1}=y_n+0.5[x_n-y_n/(x_n+3)]$.'),('A1',r'$y(0.5)\approx5/6$.'),('A1',r'$y(1)\approx27/28=0.964$.')),p('b','Find the exact solution.',2,('M1',r'$[(x+3)y]\prime=x(x+3)$.'),('A1',r'$y=(x^3/3+3x^2/2+3)/(x+3)$.')),p('c',r'Sketch the solution on $0\le x\le1$ and explain whether Euler’s estimate is above or below it.',2,('A1',rf'Convex curve from $(0,1)$, through minimum $({num(mini)},{num(f.subs(x,mini))})$, to $(1,29/24)$.'),('R1',r'$y\prime\prime=2/3+15/(x+3)^3>0$, so tangent-line steps underestimate.'))],True,'Differential equations',notes='Euler rational arithmetic, initial value, ODE substitution and second derivative checked. Source lacks a printed total; its parts total seven marks.')
add(102,'An induction identity and an integral',r'Let $n$ be a positive integer and $\sin3x\ne0$.',[p('a',r'Prove by induction that $2^n\prod_{j=0}^{n-1}\cos(3\cdot2^jx)=\sin(3\cdot2^nx)/\sin3x$.',4,('A1',r'For $n=1$, $2\cos3x=\sin6x/\sin3x$.'),('M1','Assume the identity for $n=k$.'),('M1',r'Multiply by $2\cos(3\cdot2^kx)$ and apply $2\sin u\cos u=\sin2u$.'),('R1','This gives the formula for $k+1$, completing the induction.')),p('b',r'Use this identity and Maclaurin expansions through $x^2$ to estimate $\int_0^{0.04}\cos3x\cos6x\cos12x\,dx$. Show the series division.',12,('A2',r'$\sin24x=24x-2304x^3+O(x^5)$.'),('A2',r'$\sin3x=3x-\tfrac92x^3+O(x^5)$.'),('M1',r'Write the quotient as $8(1-96x^2)/(1-\tfrac32x^2)$ to this order.'),('A1',r'$(1-\tfrac32x^2)^{-1}=1+\tfrac32x^2+O(x^4)$.'),('A1',r'$\sin24x/\sin3x=8-756x^2+O(x^4)$.'),('M1','Divide by $2^3$ to obtain the product.'),('A1',r'Product $=1-\tfrac{189}{2}x^2+O(x^4)$.'),('M1',r'Integrate: $x-\tfrac{63}{2}x^3$.'),('A1','Evaluate at $0$ and $0.04$.'),('A1',r'Estimate $0.037984\approx0.0380$.'))],True,'Maclaurin series',notes='Series coefficients independently checked by symbolic expansion of the product.')
add(103,'A derivative, translation and area',r'A quadratic $f(x)=a(x-h)^2+k$ has vertex $(4,-3)$ and $y$-intercept $-19$. A function $g$ satisfies $g\prime=f$.',[p('a','Find $a,h,k$.',4,('A1','$h=4$, $k=-3$.'),('M1','$-19=16a-3$.'),('A1','$a=-1$.'),('A1','$f=-(x-4)^2-3$.')),p('b','Show $f$ has no real zeros.',3,('M1','$f=0$ would require $(x-4)^2=-3$.'),('A1','A real square is non-negative.'),('R1','Therefore there are no real zeros.')),p('c','State and justify the monotonicity of $g$.',2,('A1','$g$ is strictly decreasing on the real line.'),('R1',r'$g\prime=f<0$ everywhere.')),p('d',r'Translate $f$ vertically to $F(x)=-(x-4)^2+m$, $m>0$. The area between $F$ and the $x$-axis is $36$. Find $m$.',6,('A1',r'Roots $4\pm\sqrt m$.'),('M1',r'Use $u=x-4$ and symmetry: $A=2\int_0^{\sqrt m}(m-u^2)du$.'),('A1',r'Primitive $mu-u^3/3$.'),('A1',r'$A=\tfrac43m^{3/2}$.'),('M1',r'$m^{3/2}=27$.'),('A1','$m=9$.')),p('e',r'If $G\prime=F$ with this $m$, state where $G$ decreases.',2,('M1','Solve $9-(x-4)^2<0$.'),('A1','$x<1$ or $x>7$.'))],sub='Applications of integration')
add(104,'A cotangent substitution',r'Use $x=2\cot\theta$ to evaluate $\int_0^2 dx/(x^2+4)^2$ exactly.',[p('a','Transform the integral.',4,('A1',r'$dx=-2\csc^2\theta\,d\theta$.'),('A1',r'$(x^2+4)^2=16\csc^4\theta$.'),('A1',r'Bounds $\theta=\pi/2,\pi/4$.'),('A1',r'The integral is $\tfrac18\int_{\pi/4}^{\pi/2}\sin^2\theta\,d\theta$.')),p('b','Hence evaluate it.',3,('M1',r'$\sin^2\theta=(1-\cos2\theta)/2$.'),('A1',r'$\tfrac1{16}[\theta-\tfrac12\sin2\theta]_{\pi/4}^{\pi/2}$.'),('A1',r'$(\pi+2)/64$.'))],sub='Integration by substitution')
add(105,'A finite trigonometric limit',r'For $x\ne0$, $f(x)=m+\sin(4x)/x^3+n/x^2$.',[p('a','Find a series expression for $f$ through its constant term.',3,('M1',r'$\sin4x=4x-\tfrac{32}{3}x^3+O(x^5)$.'),('A1',r'$\sin4x/x^3=4/x^2-32/3+O(x^2)$.'),('A1',r'$f=(4+n)/x^2+m-32/3+O(x^2)$.')),p('b',r'Find $m,n$ given that $\lim_{x\to0}f(x)=7$.',5,('R1','A finite limit requires cancellation of the $x^{-2}$ term.'),('A1','$n=-4$.'),('M1','Equate the constant term to $7$.'),('A1','$m-32/3=7$.'),('A1','$m=53/3$.'))],sub='Maclaurin series')
add(106,'Derivatives and a series limit',r'Let $f(x)=e^{2x}\cos2x$.',[p('a','Find the Maclaurin expansion through $x^4$ by differentiation.',6,('A1','$f(0)=1$.'),('M1','Apply product and chain rules repeatedly.'),('A1',r'$f\prime(0)=2$, $f\prime\prime(0)=0$.'),('A1',r'$f^{(3)}(0)=-16$, $f^{(4)}(0)=-64$.'),('M1','Divide each derivative value by its factorial.'),('A1',r'$f=1+2x-\tfrac83x^3-\tfrac83x^4+O(x^5)$.')),p('b',r'Find $\lim_{x\to0}(f(x)-1-2x)/x^3$.',3,('M1','Subtract $1+2x$ from the expansion.'),('A1',r'The quotient is $-8/3-(8/3)x+O(x^2)$.'),('A1','$-8/3$.'))],sub='Maclaurin series')
add(107,'A differential equation gives a series',r'$y\prime=2x-4xy$ and $y(0)=3$.',[p('a',r'Find an expression for $y\prime\prime$.',3,('M1','Differentiate using the product rule.'),('A1',r'$(xy)\prime=y+xy\prime$.'),('A1',r'$y\prime\prime=2-4y-4xy\prime$.')),p('b','Find the Maclaurin expansion through $x^4$.',6,('A1',r'$y\prime(0)=0$, $y\prime\prime(0)=-10$.'),('M1',r'$y^{(3)}=-8y\prime-4xy\prime\prime$.'),('A1',r'$y^{(3)}(0)=0$.'),('M1',r'$y^{(4)}=-12y\prime\prime-4xy^{(3)}$.'),('A1',r'$y^{(4)}(0)=120$.'),('A1',r'$y=3-5x^2+5x^4+O(x^6)$.'))],sub='Maclaurin series')
add(108,'Volume of a curved sculpture',r'The boundary of a sculpture is $y=\sqrt{1-16x^2}/(2x)$ for $0<x\le1/4$. Its top rim is at $x=1/8$, so its height is $k=2\sqrt3$. It is formed by revolving $0\le y\le k$, $0\le x\le1/\sqrt{4y^2+16}$ about the $y$-axis. Find its volume in the form $a\pi^2$.',[p('','',8,('M1','Square the curve equation and rearrange.'),('A1','$x^2=1/(4y^2+16)$.'),('M1','Use horizontal circular cross-sections.'),('A1',r'$V=\pi\int_0^{2\sqrt3}dy/(4y^2+16)$.'),('M1','Factor $4$ from the denominator and use an arctangent primitive.'),('A1',r'$V=\tfrac\pi8[\arctan(y/2)]_0^{2\sqrt3}$.'),('A1',r'$\arctan\sqrt3=\pi/3$.'),('A1',r'$V=\pi^2/24$, so $a=1/24$.'))],sub='Volumes of revolution',notes='The solid and finite cap are fully specified in text; squared profile and arctangent volume verified.')
add(109,'A trigonometric polynomial integral',r'Let $P(x)=1-6\sin^2(3x/2)+12\sin^4(3x/2)-8\sin^6(3x/2)$ and $f(x)=24\sin3x\,P(x)$.',[p('a',r'Expand $(1/2-k)^3$ and hence show that $P(x)=\cos^3(3x)$.',6,('M1','Apply the binomial theorem.'),('A2',r'$(1/2-k)^3=1/8-3k/4+3k^2/2-k^3$.'),('M1',r'Multiply by $8$ and put $k=\sin^2(3x/2)$.'),('A1',r'$8(1/2-k)^3=(1-2\sin^2(3x/2))^3$.'),('R1',r'$1-2\sin^2(3x/2)=\cos3x$, giving the identity.')),p('b',r'Find $a$ if $\int_{\pi/9}^a f(x)dx=-1$ and $\pi/6<a<\pi/3$.',8,('M1',r'Use $u=\cos3x$, $du=-3\sin3x\,dx$.'),('A1',r'Primitive $-2\cos^4(3x)$.'),('A1',r'Lower endpoint gives $-2(1/2)^4=-1/8$.'),('M1',r'$-2\cos^4(3a)+1/8=-1$.'),('A1',r'$\cos^4(3a)=9/16$.'),('R1',r'$\pi/2<3a<\pi$, so cosine is negative.'),('A1',r'$\cos3a=-\sqrt3/2$, hence $3a=5\pi/6$.'),('A1',r'$a=5\pi/18$.'))])
add(110,'A linear radical substitution',r'Find $\int 3x/\sqrt{1-3x}\,dx$, for $x<1/3$.',[p('','',6,('M1','$u=1-3x$, so $x=(1-u)/3$.'),('A1','$dx=-du/3$.'),('A1',r'Integral $=-\tfrac13\int(u^{-1/2}-u^{1/2})du$.'),('M1','Apply the power rule to both terms.'),('A1',r'$-\tfrac23u^{1/2}+\tfrac29u^{3/2}+C$.'),('A1',r'$-\tfrac23\sqrt{1-3x}+\tfrac29(1-3x)^{3/2}+C$.'))],sub='Integration by substitution')
add(111,'A secant substitution',r'For $x>\sqrt[3]4$, use $x^3=4\sec\theta$ to find $\int dx/[x\sqrt{x^6-16}]$.',[p('','',7,('A1',r'Choose $0<\theta<\pi/2$.'),('M1',r'$3x^2dx=4\sec\theta\tan\theta\,d\theta$.'),('A1',r'$dx/x=\tfrac13\tan\theta\,d\theta$.'),('A1',r'$\sqrt{x^6-16}=4\tan\theta$.'),('M1',r'Integral $=\tfrac1{12}\int d\theta$.'),('A1',r'$\theta/12+C$.'),('A1',r'$\tfrac1{12}\arccos(4/x^3)+C$.'))],sub='Integration by substitution')
half=(S.sqrt(17)-1)/4;dr=-5*(1+half*half)/(17*S.pi)
add(112,'A draining curved vessel',r'A vessel is obtained by revolving the region between the $y$-axis and $y=\sqrt{17/x^2-1}$, $1\le x\le\sqrt{17}$, about the $y$-axis. Its base is at $y=0$ and rim at $y=4$; all lengths are in cm.',[p('a','State the endpoints of the curve.',2,('A1','$(1,4)$.'),('A1',r'$(\sqrt{17},0)$.')),p('b','Find the inverse profile, stating its domain and range.',5,('M1','$y^2+1=17/x^2$.'),('A1',r'$x=\sqrt{17/(y^2+1)}$; take the positive root.'),('A1',r'$0\le y\le4$.'),('A1',r'$1\le x\le\sqrt{17}$.'),('R1','The original profile is strictly decreasing, so this inverse is single-valued.')),p('c','Find the water volume $V(h)$ when its depth is $h$, and the vessel’s capacity.',5,('M1',r'$V(h)=\pi\int_0^h x(y)^2dy$.'),('A1',r'$V(h)=17\pi\int_0^hdy/(1+y^2)$.'),('A1',r'$V(h)=17\pi\arctan h$.'),('M1','Substitute the rim height $h=4$.'),('A1',r'Capacity $=17\pi\arctan4$ cm$^3$.')),p('d','A full vessel drains at $5$ cm$^3$ s$^{-1}$. Find the time to empty.',2,('M1','Time equals capacity divided by constant discharge rate.'),('A1',rf'$T=17\pi\arctan4/5={num(17*S.pi*S.atan(4)/5)}$ s.')),p('e','Find the rate of decrease of depth when half the original volume remains.',6,('M1',r'$\arctan h=\tfrac12\arctan4$.'),('A1',r'$h=\tan(\tfrac12\arctan4)=(\sqrt{17}-1)/4$.'),('M1',r'$dV/dt=[17\pi/(1+h^2)]dh/dt$.'),('A1',r'$dh/dt=-5(1+h^2)/(17\pi)$.'),('M1','Substitute the half-volume depth, retaining full precision.'),('A1',rf'$dh/dt={num(dr)}$ cm s$^{{-1}}$; depth decreases at ${num(-dr)}$ cm s$^{{-1}}$.'))],True,'Volumes of revolution')
add(113,'A tangent substitution',r'Using $s=\tan x$, find $\int dx/(3+2\cos2x)$ on $-\pi/2<x<\pi/2$.',[p('','',8,('A1',r'$\cos2x=(1-s^2)/(1+s^2)$.'),('A1',r'$dx=ds/(1+s^2)$.'),('M1','Substitute both expressions into the integral.'),('A1',r'$3+2\cos2x=(5+s^2)/(1+s^2)$.'),('A1',r'Integral $=\int ds/(s^2+5)$.'),('M1',r'Use $\int du/(a^2+u^2)=a^{-1}\arctan(u/a)+C$.'),('A1',r'$\tfrac1{\sqrt5}\arctan(s/\sqrt5)+C$.'),('A1',r'$\tfrac1{\sqrt5}\arctan(\tan x/\sqrt5)+C$.'))],sub='Integration by substitution')
add(114,'A logarithmic series with a general term',r'Let $f(x)=3(1-x)\ln(1-x)+3x$.',[p('a','By differentiation, find the first five non-zero Maclaurin terms.',8,('A1',r'$f(0)=f\prime(0)=0$.'),('M1',r'$f\prime=-3\ln(1-x)$.'),('A1',r'$f\prime\prime=3/(1-x)$.'),('A1',r'$f^{(n)}=3(n-2)!/(1-x)^{n-1}$ for $n\ge2$.'),('M1','Divide the derivatives at zero by $n!$.'),('A1',r'First two terms $\tfrac32x^2+\tfrac12x^3$.'),('A1',r'Next two terms $\tfrac14x^4+\tfrac3{20}x^5$.'),('A1',r'Fifth term $\tfrac1{10}x^6$.')),p('b','Give the general term and an interval where the series is valid.',2,('A1',r'$\displaystyle\sum_{n=2}^\infty\frac{3x^n}{n(n-1)}$.'),('A1','$|x|<1$.'))],sub='Maclaurin series')
add(115,'An induction formula for derivatives',r'Let $f(x)=(3x+1)e^{3x}$.',[p('a',r'Find $f\prime$.',2,('M1','Use the product rule.'),('A1',r'$f\prime=3e^{3x}(3x+2)$.')),p('b',r'Prove by induction that $f^{(n)}=3^{n+1}e^{3x}[x+(n+1)/3]$ for $n\ge1$.',6,('A1','The case $n=1$ is part (a).'),('M1','Assume the formula holds for $n=k$.'),('M1','Differentiate with the product rule.'),('A1',r'$f^{(k+1)}=3^{k+1}e^{3x}[3x+(k+1)+1]$.'),('A1',r'$=3^{k+2}e^{3x}[x+(k+2)/3]$.'),('R1','This is the required next case, completing the proof.')),p('c',r'The coefficient of $x^2$ in $\cos(kx)/f(x)$ is zero. Find all real $k$.',6,('M1',r'$1/f=e^{-3x}(1+3x)^{-1}$.'),('A1',r'$e^{-3x}=1-3x+\tfrac92x^2+O(x^3)$.'),('A1',r'$(1+3x)^{-1}=1-3x+9x^2+O(x^3)$.'),('A1',r'$1/f=1-6x+\tfrac{45}{2}x^2+O(x^3)$.'),('M1',r'$45/2-k^2/2=0$ after multiplication by $1-k^2x^2/2$.'),('A1',r'$k=\pm3\sqrt5$.'))],sub='Maclaurin series')
add(116,'Logarithmic maximum and inflexion',r'Let $f(x)=\ln(27x^3)/(kx)$, where $x>0$ and $k>0$. Let A be its maximum and B its inflexion point.',[p('a','Find the abscissa of A.',4,('M1','Differentiate by the quotient rule.'),('A1',r'$f\prime=(3-\ln(27x^3))/(kx^2)$.'),('M1',r'$\ln(27x^3)=3$.'),('A1','$x_A=e/3$.')),p('b','Find the abscissa of B.',3,('A1',r'$f\prime\prime=[2\ln(27x^3)-9]/(kx^3)$.'),('M1',r'$\ln(27x^3)=9/2$.'),('A1','$x_B=e^{3/2}/3$.')),p('c','Justify the descriptions maximum and inflexion.',3,('R1',r'$f\prime$ changes from positive to negative at A.'),('A1',r'$f\prime\prime$ is negative before B and positive after B.'),('R1','Thus concavity changes at B.')),p('d','The area under $f$ between A and B is $6$. Find $k$ exactly.',8,('A1',r'$\ln(27x^3)=3\ln(3x)$.'),('M1',r'$A=(3/k)\int_{e/3}^{e^{3/2}/3}\ln(3x)/x\,dx$.'),('M1',r'Use $u=\ln(3x)$, $du=dx/x$.'),('A1','New bounds $1$ and $3/2$.'),('A1',r'$A=\tfrac3{2k}[u^2]_1^{3/2}$.'),('A1','$A=15/(8k)$.'),('M1','$15/(8k)=6$.'),('A1','$k=5/16$.'))])
