add(117,'Euler steps after integrating acceleration',r'$y\prime\prime=-12xe^{-x^2}$, $y(0)=-2$, and $y\prime(0)=3$.',[p('a',r'Find $y\prime$ in terms of $x$.',2,('M1',r'$y\prime=6e^{-x^2}+C$ and $3=6+C$.'),('A1',r'$y\prime=6e^{-x^2}-3$.')),p('b','Use Euler’s method with step $0.1$ to estimate $y(0.5)$.',4,('M1',r'$y_{n+1}=y_n+0.1(6e^{-x_n^2}-3)$.'),('A1',rf'Values at $0.1,0.2$: ${num(tab[0],6)}, {num(tab[1],6)}$.'),('A1',rf'Values at $0.3,0.4$: ${num(tab[2],6)}, {num(tab[3],6)}$.'),('A1',rf'$y(0.5)\approx{num(tab[4])}$.')),p('c','State whether this is an overestimate or underestimate, with a reason.',2,('A1','Overestimate.'),('R1',r'$y\prime\prime<0$ for $x>0$, so the tangent segments lie above the curve.'))],True,'Differential equations')
add(118,'Distance by substitution and parts',r'A particle has velocity $v(t)=24t^3e^{-2t^2}$ m s$^{-1}$ for $t\ge0$. Find the distance travelled in the first $2$ seconds exactly.',[p('','',5,('M1',r'$D=\int_0^2v(t)dt$, since $v\ge0$.'),('A1',r'$u=t^2$ gives $D=12\int_0^4ue^{-2u}du$.'),('M1','Integrate by parts.'),('A1',r'Primitive $-6ue^{-2u}-3e^{-2u}$.'),('A1',r'$D=3-27e^{-8}$ m.'))],sub='Kinematics')
