add(119,'A homogeneous equation and its model range',r'Consider $y\prime-2=3(2xy+y^2)/x^2$, with $y(3)=0$.',[p('a','Use Euler’s method with step $0.25$ to estimate $y(4.25)$.',4,('M1','$y_{n+1}=y_n+0.25[2+6y_n/x_n+3y_n^2/x_n^2]$.'),('A1',rf'At $3.25,3.5$: ${num(eul[0],6)}, {num(eul[1],6)}$.'),('A1',rf'At $3.75,4$: ${num(eul[2],6)}, {num(eul[3],6)}$.'),('A1',rf'$y(4.25)\approx{num(eul[4])}$.')),p('b','Use $y=vx$ to find the exact solution on the interval containing $x=3$.',10,('A1',r'$y\prime=v+xv\prime$.'),('A1',r'$xv\prime=3v^2+5v+2=(v+1)(3v+2)$.'),('M1',r'$\int dv/[(v+1)(3v+2)]=\int dx/x$.'),('A1',r'$1/[(v+1)(3v+2)]=-1/(v+1)+3/(3v+2)$.'),('A1',r'$\ln|(3v+2)/(v+1)|=\ln|x|+C$.'),('M1','Use $v=0$ at $x=3$.'),('A1','$(3v+2)/(v+1)=2x/3$.'),('M1','Solve for $v$, then multiply by $x$.'),('A1','$y=x(2x/3-2)/(3-2x/3)$.'),('A1','$0<x<9/2$ is the maximal interval containing $3$.')),p('c','Evaluate $y(4.25)$ exactly and compare with (a).',2,('A1','$y(4.25)=85/4=21.25$.'),('R1','Euler gives a substantial underestimate as the solution steepens near its pole.')),p('d',r'The same formula defines a voltage $V(d)$ for $d\ge0$. State the excluded input.',1,('A1','$d=9/2$.')),p('e','Find the open interval of values that $V$ cannot take.',3,('M1','$2d^2+(2V-6)d-9V=0$.'),('A1',r'Discriminant $=4(V^2+12V+9)\ge0$; at least one root $d$ is non-negative when $V\le-6-3\sqrt3$ or $V\ge-6+3\sqrt3$.'),('A1',r'Excluded interval $(-6-3\sqrt3,-6+3\sqrt3)$.'))],True,'Differential equations',notes='Exact ODE substitution, Euler recurrence and quadratic-discriminant range checked.')
add(120,'Exponential integrals of products',r'Let $I_n=\int_0^{2\pi}e^{2x}\cos(nx)dx$, where $n$ is a positive integer.',[p('a','Use integration by parts twice to find $I_3$.',7,('M1',r'Let $J=\int_0^{2\pi}e^{2x}\sin3x\,dx$.'),('M1','Integrate $I_3$ by parts using $dv=e^{2x}dx$.'),('A1',r'$I_3=(e^{4\pi}-1)/2+(3/2)J$.'),('M1','Integrate $J$ by parts in the same way.'),('A1','$J=-(3/2)I_3$ because the sine boundary term vanishes.'),('M1',r'Substitute and solve $(13/4)I_3=(e^{4\pi}-1)/2$.'),('A1',r'$I_3=\tfrac2{13}(e^{4\pi}-1)$.')),p('b',r'Find $a$ such that $\int_0^{2\pi}e^{2x}\cos4x\cos2x\,dx=a(e^{4\pi}-1)$.',6,('M1',r'The same calculation gives $I_n=2(e^{4\pi}-1)/(4+n^2)$.'),('A1',r'$2\cos4x\cos2x=\cos6x+\cos2x$.'),('M1','The required integral is $(I_6+I_2)/2$.'),('A1',r'$I_6=(e^{4\pi}-1)/20$.'),('A1',r'$I_2=(e^{4\pi}-1)/4$.'),('A1','$a=3/20$.')),p('c',r'Find $b$ such that $\int_0^{2\pi}e^{2x}\sin5x\sin3x\,dx=b(e^{4\pi}-1)$.',5,('A1',r'$2\sin5x\sin3x=\cos2x-\cos8x$.'),('M1','Use $(I_2-I_8)/2$.'),('A1',r'$I_8=(e^{4\pi}-1)/34$.'),('M1','$b=(1/4-1/34)/2$.'),('A1','$b=15/136$.'))],sub='Integration by parts')
