add(121,'A linear equation and Euler error',r'$y\prime-y/x=2/3$ for $x>0$, with $y(1)=3$.',[p('a','Use Euler’s method with step $0.5$ to estimate $y(3)$, giving the answer to two significant figures.',6,('M1','$y_{n+1}=y_n+0.5(y_n/x_n+2/3)$.'),('A1',rf'$y(1.5)\approx{num(et[0],7)}$.'),('A1',rf'$y(2)\approx{num(et[1],7)}$.'),('A1',rf'$y(2.5)\approx{num(et[2],7)}$.'),('A1',rf'Unrounded final estimate ${num(et[3],9)}$.'),('A1',rf'To two significant figures: ${num(rounded,2)}$.')),p('b','Find the exact solution.',6,('M1',r'Integrating factor $e^{\int-1/x\,dx}$.'),('A1',r'$\mu=1/x$.'),('A1',r'$(y/x)\prime=2/(3x)$.'),('M1','Integrate both sides.'),('A1',r'$y/x=(2/3)\ln x+C$, $C=3$.'),('A1',r'$y=x[3+(2/3)\ln x]$.')),p('c','Find the percentage error of the rounded estimate in (a).',3,('A1',rf'Exact value $9+2\ln3={num(trueval,9)}$.'),('M1',r'Error $=100|\text{estimate}-\text{exact}|/|\text{exact}|$.'),('A1',rf'Percentage error ${num(err)}\%$.'))],True,'Differential equations')
add(122,'A recurrence for Maclaurin coefficients',r'Let $f(x)=e^{2x}\cos2x$.',[p('a',r'Show that $f\prime\prime=4(f\prime-2f)$.',4,('M1','Apply the product rule.'),('A1',r'$f\prime=2e^{2x}(\cos2x-\sin2x)$.'),('A1',r'$f\prime\prime=-8e^{2x}\sin2x$.'),('R1',r'$4(f\prime-2f)=-8e^{2x}\sin2x=f\prime\prime$.')),p('b','Hence find the Maclaurin expansion through $x^5$.',5,('M1',r'$f^{(n+2)}(0)=4f^{(n+1)}(0)-8f^{(n)}(0)$.'),('A1',r'$f(0)=1$, $f\prime(0)=2$.'),('A1',r'Next derivative values $0,-16,-64,-128$.'),('M1','Divide by the corresponding factorials.'),('A1',r'$1+2x-\tfrac83x^3-\tfrac83x^4-\tfrac{16}{15}x^5+O(x^6)$.'))],sub='Maclaurin series')
add(123,'Composition with an algebraic function',r'Let $f(x)=\sin2x$ on $[-\pi/4,\pi/4]$ and $g(u)=2u\sqrt{1-u^2}/(1-2u^2)$ for $u\in[-1,1]\setminus\{\pm1/\sqrt2\}$.',[p('a','State the range of $f$.',2,('M1',r'$2x\in[-\pi/2,\pi/2]$.'),('A1','$[-1,1]$.')),p('b',r'Simplify $h=g\circ f$ and state its domain.',2,('A1',r'$h(x)=\tan4x$, since $\sqrt{1-\sin^22x}=\cos2x\ge0$.'),('A1',r'$[-\pi/4,\pi/4]\setminus\{-\pi/8,\pi/8\}$.')),p('c',r'Using the chain rule on $g\circ f$, find $h\prime(\pi/12)$.',6,('A1',r'$f(\pi/12)=1/2$.'),('A1',r'$f\prime(\pi/12)=2\cos(\pi/6)=\sqrt3$.'),('M1','Differentiate $g$ using quotient and chain rules.'),('A1',r'$g\prime(u)=2/[\sqrt{1-u^2}(1-2u^2)^2]$.'),('A1',r'$g\prime(1/2)=16/\sqrt3$.'),('A1',r'$h\prime(\pi/12)=16$.')),p('d',r'Find the area under $h$ from $0$ to $\pi/12$ exactly.',6,('R1',r'$h\ge0$ throughout this interval and no pole lies inside it.'),('M1',r'$A=\int_0^{\pi/12}\tan4x\,dx$.'),('M1',r'Use $u=\cos4x$, $du=-4\sin4x\,dx$.'),('A1',r'Primitive $-\tfrac14\ln|\cos4x|$.'),('A1',r'$A=-\tfrac14\ln(1/2)+\tfrac14\ln1$.'),('A1',r'$A=\tfrac14\ln2$.'))])
