add(124,'Area between two trigonometric curves',r'Let $f(x)=6\cos2x$ and $g(x)=3-12\cos x$ for $0<x<2\pi$.',[p('a','Find all intersections exactly.',7,('M1',r'$6(2\cos^2x-1)=3-12\cos x$.'),('A1',r'$4\cos^2x+4\cos x-3=0$.'),('M1',r'Factor or solve the quadratic in $\cos x$.'),('A1',r'$\cos x=1/2$ or $-3/2$.'),('R1','Reject $-3/2$ since cosine lies in $[-1,1]$.'),('A1',r'$x=\pi/3,5\pi/3$.'),('A1','Both intersection ordinates are $-3$.')),p('b','Find the enclosed area.',6,('R1','$g>f$ between these intersections.'),('M1',r'$A=\int_{\pi/3}^{5\pi/3}(3-12\cos x-6\cos2x)dx$.'),('A1',r'Primitive $3x-12\sin x-3\sin2x$.'),('A1',r'Linear contribution $4\pi$.'),('A1',r'Sine contributions $12\sqrt3+3\sqrt3$.'),('A1',r'$A=4\pi+15\sqrt3$.')),p('c',r'At points where the curves have equal gradients and $\sin x\ne0$, show that the ordinate on $g$ is $9$.',5,('M1',r'$-12\sin2x=12\sin x$.'),('A1',r'$\sin x(2\cos x+1)=0$.'),('R1',r'The stated restriction excludes $\sin x=0$.'),('A1',r'$\cos x=-1/2$.'),('R1','$g(x)=3-12(-1/2)=9$.'))],notes='The non-stationary condition in (c) explicitly excludes the additional equal-gradient point x=pi.')
add(125,'Filling a shaped vase',r'A vase has circular cross-sections of radius $r(h)=9+4\sin(\pi h/20)$ cm at height $h$ cm, $0\le h\le40$. Water enters at $120$ cm$^3$ s$^{-1}$.',[p('a','Find its capacity exactly.',8,('M1',r'$V=\pi\int_0^{40}r(h)^2dh$.'),('A1',r'$r^2=81+72\sin(\pi h/20)+16\sin^2(\pi h/20)$.'),('M1',r'Use $\sin^2u=(1-\cos2u)/2$.'),('A1',r'$r^2=89+72\sin(\pi h/20)-8\cos(\pi h/10)$.'),('A1',r'Primitive $89h-(1440/\pi)\cos(\pi h/20)-(80/\pi)\sin(\pi h/10)$.'),('M1','Evaluate at $0,40$.'),('A1','Periodic terms cancel.'),('A1',r'$V=3560\pi$ cm$^3$.')),p('b','Find the rate of increase of depth when $h=30$.',4,('M1','$dV/dt=(dV/dh)(dh/dt)$.'),('A1',r'$dh/dt=120/(\pi r^2)$.'),('A1','$r(30)=5$.'),('A1',r'$dh/dt=24/(5\pi)$ cm s$^{-1}$.')),p('c','Find the depths where $d^2h/dt^2=0$ and classify the corresponding depth rates.',7,('M1',r'Differentiate $120/(\pi r^2)$ with respect to $h$ and multiply by $dh/dt$.'),('A1',r'$r\prime(h)=(\pi/5)\cos(\pi h/20)$.'),('A1',r'$d^2h/dt^2=-5760\cos(\pi h/20)/(\pi r^5)$.'),('M1',r'$\cos(\pi h/20)=0$.'),('A1','$h=10,30$.'),('R1','At $h=10$, radius $13$ is maximal, so the depth rate is minimal.'),('R1','At $h=30$, radius $5$ is minimal, so the depth rate is maximal.'))],sub='Volumes of revolution')
add(126,'Motion with linear resistance',r'A particle starts at $s=0$ with velocity $v_0>0$ and acceleration $dv/dt=-2(v+4)$.',[p('a','Find its velocity and the time $T$ when it first comes to rest.',6,('M1',r'$dv/(v+4)=-2dt$.'),('A1',r'$\ln(v+4)=-2t+C$ initially.'),('M1','Use $v(0)=v_0$.'),('A1','$v=(v_0+4)e^{-2t}-4$.'),('M1','Set $v(T)=0$.'),('A1',r'$T=\tfrac12\ln(1+v_0/4)$.')),p('b','Find the displacement and maximum displacement.',8,('M1','Integrate the velocity.'),('A1','$s=-(v_0+4)e^{-2t}/2-4t+C$.'),('M1','Use $s(0)=0$.'),('A1','$C=(v_0+4)/2$.'),('A1','$s=(v_0+4)(1-e^{-2t})/2-4t$.'),('R1','Velocity is positive before $T$ and negative after it, so $s$ is maximal at $T$.'),('M1','Substitute $e^{-2T}=4/(v_0+4)$.'),('A1',r'$s_{max}=v_0/2-2\ln(1+v_0/4)$.')),p('c',r'For $0\le k\le T$, find $v(T-k)$.',2,('M1','Use $(v_0+4)e^{-2T}=4$.'),('A1','$v(T-k)=4e^{2k}-4$.')),p('d','Find $v(T+k)$.',2,('M1','Apply the same substitution at $T+k$.'),('A1','$v(T+k)=4e^{-2k}-4$.')),p('e',r'Show that $v(T-k)+v(T+k)\ge0$.',3,('A1','$v(T-k)+v(T+k)=4(e^{2k}+e^{-2k}-2)$.'),('M1','$e^{2k}+e^{-2k}-2=(e^k-e^{-k})^2$.'),('R1','A real square is non-negative, proving the result.'))],sub='Kinematics')
