add(127,'Perpendicular curves and Euler’s method',r'Two curves $y=f(x)$ and $y=g(x)$ pass through $(2,0)$ and obey $f\prime=x-f^2$, $g\prime=2g-x/4$.',[p('a','Show that they meet at right angles.',2,('A1','Their gradients at $(2,0)$ are $2$ and $-1/2$.'),('R1','The product is $-1$, so the tangents are perpendicular.')),p('b','Find $g(x)$ exactly.',7,('M1',r'Write $g\prime-2g=-x/4$; integrating factor $e^{-2x}$.'),('A1',r'$(e^{-2x}g)\prime=-(x/4)e^{-2x}$.'),('M1','Integrate by parts.'),('A1',r'$e^{-2x}g=e^{-2x}(x/8+1/16)+C$.'),('M1','Use $g(2)=0$.'),('A1','$C=-5e^{-4}/16$.'),('A1','$g=x/8+1/16-(5/16)e^{2x-4}$.')),p('c','Use Euler’s method with step $0.2$ to estimate $f(3)$, to five decimal places.',5,('M1','$f_{n+1}=f_n+0.2(x_n-f_n^2)$.'),('A1',rf'At $2.2,2.4$: ${num(fe[0],8)}, {num(fe[1],8)}$.'),('A1',rf'At $2.6$: ${num(fe[2],8)}$.'),('A1',rf'At $2.8$: ${num(fe[3],8)}$.'),('A1',rf'$f(3)\approx{fe[4]:.5f}$.'))],True,'Differential equations')
add(128,'A radical integrating factor',r'$y\prime+\dfrac{3x^5}{1+x^6}y=6x^5$, with $y(0)=2$.',[p('a','Find an integrating factor.',4,('M1',r'$\mu=e^{\int3x^5/(1+x^6)dx}$.'),('M1','Use $u=1+x^6$.'),('A1',r'The exponent is $\tfrac12\ln(1+x^6)$.'),('A1',r'$\mu=\sqrt{1+x^6}$.')),p('b','Find the solution.',6,('M1',r'$[\sqrt{1+x^6}\,y]\prime=6x^5\sqrt{1+x^6}$.'),('M1','Integrate with $u=1+x^6$.'),('A1',r'$\sqrt{1+x^6}\,y=\tfrac23(1+x^6)^{3/2}+C$.'),('M1','Use the initial condition.'),('A1','$C=4/3$.'),('A1',r'$y=\tfrac23(1+x^6)+\dfrac4{3\sqrt{1+x^6}}$.'))],sub='Differential equations')
add(129,'An improper exponential integral',r'Consider $I=\int_0^\infty x^4e^{-2x}dx$.',[p('a',r'Show that $\lim_{x\to\infty}x^4e^{-2x}=0$.',4,('M1','Write the expression as $x^4/e^{2x}$.'),('M1','Apply l’Hôpital’s rule repeatedly to the infinity-over-infinity forms.'),('A1','After four applications the quotient is $24/(16e^{2x})$.'),('R1','This tends to $0$, as required.')),p('b','Evaluate $I$ exactly, justifying the convergence.',9,('M1',r'Use $I_n=\lim_{b\to\infty}\int_0^b x^ne^{-2x}dx$.'),('M1','Integrate by parts with $u=x^n$, $dv=e^{-2x}dx$.'),('A1',r'$I_n=[-x^ne^{-2x}/2]_0^\infty+(n/2)I_{n-1}$ for $n\ge1$.'),('R1','The boundary term vanishes; the exponential dominates each power, as in (a).'),('A1','$I_0=1/2$.'),('A1','$I_1=1/4$.'),('A1','$I_2=1/4$, $I_3=3/8$.'),('A1','$I_4=3/4$.'),('R1','The finite recursively obtained limit establishes convergence.'))],sub='Improper integrals')
add(130,'A rational exponential curve',r'Let $f(x)=ae^{-2x}/(b-ae^{-2x})$, where $a,b>0$.',[p('a',r'Find $f\prime$.',3,('M1','Use the quotient rule.'),('A1',r'Numerator simplifies to $-2abe^{-2x}$.'),('A1',r'$f\prime=-2abe^{-2x}/(b-ae^{-2x})^2$.')),p('b','Show that there are no inflexion points.',5,('M1','Differentiate the first derivative.'),('A1',r'$f\prime\prime=4abe^{-2x}(b+ae^{-2x})/(b-ae^{-2x})^3$.'),('A1','The numerator is positive everywhere.'),('R1','The second derivative is never zero on either connected branch.'),('R1','Its sign changes only across the undefined asymptote, which is not a point of the curve.')),p('c','State all vertical and horizontal asymptotes.',2,('A1',r'$x=\tfrac12\ln(a/b)$.'),('A1',r'$y=0$ as $x\to\infty$, and $y=-1$ as $x\to-\infty$.')),p('d','State the monotonicity.',1,('A1','Strictly decreasing on each side of the vertical asymptote.')),p('e',r'For $a=4,b=1$, sketch both branches and find the area bounded by the curve, the axes and $x=\tfrac12\ln2$.',5,('A1',r'Asymptote $x=\ln2$; left branch below $-1$, passing through $(0,-4/3)$; right branch positive, approaching $0$.'),('M1',r'Area $=-\int_0^{(\ln2)/2}f(x)dx$.'),('M1','Use $u=1-4e^{-2x}$.'),('A1',r'Primitive of $f$ is $\tfrac12\ln|1-4e^{-2x}|$.'),('A1',r'Area $=\tfrac12\ln3$.'))],notes='Both horizontal asymptotes included; discontinuity is not misidentified as an inflexion point.')
add(131,'An inverse cosine differential identity',r'Let $f(x)=[\arccos(2x)]^2$, $|x|<1/2$.',[p('a',r'Find $f\prime(0)$.',2,('M1',r'$f\prime=-4\arccos(2x)/\sqrt{1-4x^2}$.'),('A1',r'$f\prime(0)=-2\pi$.')),p('b',r'Show that $(1-4x^2)f\prime\prime-4xf\prime=8$.',4,('M1','Differentiate the expression in (a).'),('A1',r'$f\prime\prime=8/(1-4x^2)-16x\arccos(2x)/(1-4x^2)^{3/2}$.'),('A1',r'The second term equals $4xf\prime/(1-4x^2)$.'),('R1','Multiplication and rearrangement gives the identity.')),p('c','Differentiate the identity twice and obtain the Maclaurin expansion through $x^4$.',5,('A1',r'First derivative: $(1-4x^2)f^{(3)}-12xf\prime\prime-4f\prime=0$.'),('A1',r'Second: $(1-4x^2)f^{(4)}-20xf^{(3)}=16f\prime\prime$.'),('M1','Substitute $x=0$ successively.'),('A1',r'$f\prime\prime(0)=8$, $f^{(3)}(0)=-8\pi$, $f^{(4)}(0)=128$.'),('A1',r'$f=\pi^2/4-2\pi x+4x^2-\tfrac{4\pi}{3}x^3+\tfrac{16}{3}x^4+O(x^5)$.')),p('d',r'Use $x=1/4$ and your series to show that $75\pi-20\pi^2\approx39$.',3,('A1',r'$f(1/4)=(\arccos(1/2))^2=\pi^2/9$.'),('M1',r'$\pi^2/9\approx\pi^2/4-25\pi/48+13/48$.'),('R1','Multiply by $144$ and rearrange to obtain the stated approximation.'))],sub='Maclaurin series')
add(132,'Two parabolic regions of equal area',r'Region A lies between $y=x^2$ and $y=3x^2$ for $0\le x\le a$, where $a>0$. Region B lies between the positive branches $y=3x^2$ and $y=kx^2$ and the horizontal line $y=3a^2$, with $k>3$.',[p('a','Find the area of A.',1,('A1',r'$A=\int_0^a2x^2dx=2a^3/3$.')),p('b','Given that A and B have equal area, find $k$.',7,('A1',r'Horizontal width of B is $\sqrt{y/3}-\sqrt{y/k}$.'),('M1',r'$B=\int_0^{3a^2}(1/\sqrt3-1/\sqrt k)\sqrt y\,dy$.'),('A1',r'Primitive $\tfrac23(1/\sqrt3-1/\sqrt k)y^{3/2}$.'),('A1',r'$B=2a^3(1-\sqrt{3/k})$.'),('M1','Equate this to $2a^3/3$ and cancel $2a^3$.'),('A1',r'$\sqrt{3/k}=2/3$.'),('A1','$k=27/4$.'))],notes='Both regions have complete boundary descriptions; no missing source diagram is needed.')
add(133,'A general homogeneous substitution',r'For $x>0$, consider $y\prime=F(y/x)$.',[p('a',r'Show how $y=vx$ gives a separated equation. Mention any solutions that division could lose.',4,('A1',r'$y\prime=v+xv\prime$.'),('A1',r'$xv\prime=F(v)-v$.'),('M1',r'$dv/[F(v)-v]=dx/x$ when the denominator is non-zero.'),('R1','Also check constant $v$ satisfying $F(v)=v$, giving straight-line solutions.')),p('b',r'Solve $y\prime=(6x^2+6xy+y^2)/x^2$, with $y(1)=1$.',9,('M1','Use $y=vx$.'),('A1',r'$xv\prime=v^2+5v+6=(v+2)(v+3)$.'),('M1','Separate and use partial fractions.'),('A1',r'$1/[(v+2)(v+3)]=1/(v+2)-1/(v+3)$.'),('A1',r'$\ln|(v+2)/(v+3)|=\ln x+C$.'),('M1','Use $v(1)=1$.'),('A1','$(v+2)/(v+3)=3x/4$.'),('A1','$y=x(9x-8)/(4-3x)$, on $0<x<4/3$.'),('R1','The omitted constant-ratio solutions $y=-2x,-3x$ do not satisfy the initial condition.'))],sub='Differential equations')
add(134,'A parameter in a linear equation',r'Let $p$ be a positive integer. On $x>0$, $xy\prime+y=2x^{p+1}$ and $y(1)=2$.',[p('a','Find $y$ explicitly.',8,('M1',r'Divide by $x$: $y\prime+y/x=2x^p$.'),('A1',r'Integrating factor $e^{\int dx/x}=x$.'),('A1',r'$(xy)\prime=2x^{p+1}$.'),('M1','Integrate both sides.'),('A1','$xy=2x^{p+2}/(p+2)+C$.'),('M1','Use $(x,y)=(1,2)$.'),('A1','$C=2(p+1)/(p+2)$.'),('A1','$y=2[x^{p+1}+(p+1)/x]/(p+2)$.')),p('b',r'Extend this same algebraic expression to every $x\ne0$. For which $p$ does the extended graph have two stationary points?',4,('M1',r'$y\prime=2(p+1)(x^p-x^{-2})/(p+2)$.'),('A1','Stationarity requires $x^{p+2}=1$.'),('R1',r'There are two real roots, $x=\pm1$, exactly when $p+2$ is even.'),('A1','$p$ is any positive even integer.'))],sub='Differential equations',notes='The negative-x branch is explicitly an algebraic extension, rather than claiming an initial condition across a singularity determines it.')
f=S.sqrt(x)/(3*S.cos(x));st=roots(S.diff(f,x),math.pi/2+.001,math.pi-.001,x)[0];normal=roots(S.diff(f,x)-2,math.pi/2+.001,st,x)[0];vol=S.pi/9*(x*S.tan(x)+S.log(S.Abs(S.cos(x))));vv=float((vol.subs(x,4*S.pi/3)-vol.subs(x,3*S.pi/4)).evalf())
add(135,'A radical-trigonometric profile',r'Let $f(x)=\sqrt{x}/(3\cos x)$ for $\pi/2<x<3\pi/2$.',[p('a','Find the stationary point and classify it.',7,('M1','Differentiate the quotient.'),('A1',r'$f\prime=(\cos x+2x\sin x)/(6\sqrt x\cos^2x)$.'),('A1',r'Equivalent form $(1+2x\tan x)/(6\sqrt x\cos x)$.'),('M1',r'Solve $1+2x\tan x=0$ numerically.'),('A1',rf'Stationary point $({num(st)},{num(f.subs(x,st))})$.'),('A1','The derivative changes from positive to negative there.'),('R1','It is a local maximum (and the unique maximum on the domain).')),p('b','State the intervals where $f$ increases and decreases.',3,('M1',r'Use the sign of the numerator of $f\prime$; its denominator is positive.'),('A1',rf'Increasing on $(\pi/2,{num(st)})$.'),('A1',rf'Decreasing on $({num(st)},3\pi/2)$.')),p('c','Find the point where the normal is perpendicular to $y=2x$. Give coordinates to two decimal places.',4,('A1','Normal slope $-1/2$, so tangent slope $2$.'),('M1',r'Solve $f\prime(x)=2$ on the domain.'),('A1',rf'$x={normal:.2f}$.'),('A1',rf'$y={float(f.subs(x,normal)):.2f}$.')),p('d',r'Find the volume formed by revolving the region between $f$ and the $x$-axis from $3\pi/4$ to $4\pi/3$ about the $x$-axis. Give two decimal places.',3,('M1',r'$V=(\pi/9)\int_{3\pi/4}^{4\pi/3}x\sec^2x\,dx$.'),('A1',r'By parts, primitive $(\pi/9)[x\tan x+\ln|\cos x|]$.'),('A1',rf'$V={vv:.2f}$ cubic units.'))],True,'Applications of integration',notes='PDF radical was inspected visually. Stationary point, normal-slope root and finite volume recomputed numerically.')
add(136,'Symmetry and signed area',r'Let $f(x)=(2-x)\sqrt{4x-x^2}$.',[p('a','Find its real domain.',3,('M1',r'$4x-x^2\ge0$.'),('A1',r'$x(4-x)\ge0$.'),('A1','$[0,4]$.')),p('b',r'Show that $f(2-u)=-f(2+u)$ and describe the symmetry.',4,('A1',r'$f(2-u)=u\sqrt{4-u^2}$.'),('A1',r'$f(2+u)=-u\sqrt{4-u^2}$.'),('R1',r'They are negatives for $-2\le u\le2$.'),('A1','The curve has rotational symmetry of order two about $(2,0)$.')),p('c','Find the stationary-point abscissae.',3,('M1',r'Set $z=x-2$, so $f=-z\sqrt{4-z^2}$.'),('A1',r'$f\prime=(2z^2-4)/\sqrt{4-z^2}$.'),('A1',r'$x=2\pm\sqrt2$.')),p('d','Find the range of $f$.',3,('A1',r'$f(2-\sqrt2)=2$ and $f(2+\sqrt2)=-2$.'),('M1','Compare these with endpoint values $0$.'),('A1','$[-2,2]$.')),p('e','Sketch the graph with intercepts and extreme points.',3,('A1','Intercepts $(0,0),(2,0),(4,0)$.'),('A1',r'Maximum $(2-\sqrt2,2)$, minimum $(2+\sqrt2,-2)$.'),('A1','Positive first lobe and negative second lobe, with the symmetry from (b).')),p('f','Find the area between the graph and the axis from $0$ to $2$.',2,('M1',r'Use $u=4x-x^2$, $du=2(2-x)dx$; area $=\tfrac12\int_0^4\sqrt u\,du$.'),('A1','$8/3$.')),p('g',r'Compare $\int_0^4|f(x)|dx$ and $|\int_0^4f(x)dx|$.',2,('A1','The first is $16/3$ by equal positive lobe areas.'),('A1','The second is $0$ because the signed lobes cancel.'))])
add(137,'A sine-cubed density',r'Let $f(x)=\sin^3(3x)$.',[p('a',r'Show that $\sin^3\theta=\sin\theta-\sin\theta\cos^2\theta$.',1,('R1',r'Factor $\sin\theta(1-\cos^2\theta)=\sin^3\theta$.')),p('b',r'Find $\int f(x)dx$.',4,('M1','Use the identity from (a).'),('A1',r'$\int\sin3x\,dx=-\cos3x/3$.'),('M1',r'For the other term, use $u=\cos3x$.'),('A1',r'Primitive $\cos^3(3x)/9-\cos3x/3+C$.')),p('c',r'A density is $a f(x)$ on $0\le x\le\pi/6$ and zero elsewhere. Find $a$ and $P(\pi/9<X<\pi/6)$.',4,('M1',r'$1=a\int_0^{\pi/6}f(x)dx=a(2/9)$.'),('A1','$a=9/2$.'),('M1',r'Evaluate $(9/2)[\cos^3(3x)/9-\cos3x/3]_{\pi/9}^{\pi/6}$.'),('A1','$11/16$.'))],sub='Integration and probability')
add(138,'Logistic growth',r'A population satisfies $dN/dt=2kN(L-N)/L$, with $k>0$, $0<N(0)=N_0<L/2$.',[p('a','Find $d^2N/dt^2$ in terms of $N$.',4,('M1','Differentiate with respect to $t$ using the chain rule.'),('A1',r'$N\prime\prime=(2k/L)(L-2N)N\prime$.'),('M1','Substitute the original equation.'),('A1',r'$N\prime\prime=(2k/L)^2N(L-N)(L-2N)$.')),p('b','Find the population and growth rate when growth is fastest.',5,('M1',r'View $N\prime$ as a downward quadratic in $N$.'),('A1','Its stationary value occurs at $L-2N=0$.'),('A1','$N=L/2$.'),('R1','The quadratic is concave down, so this is a maximum.'),('A1','Maximum growth rate $kL/2$.')),p('c','Explain the change in concavity of $N(t)$.',2,('R1',r'$N\prime\prime>0$ for $N<L/2$.'),('R1',r'$N\prime\prime<0$ for $N>L/2$, so the inflexion occurs at half capacity.')),p('d','Solve the equation in a form relating $t$ and $N$.',7,('M1',r'$L\,dN/[N(L-N)]=2k\,dt$.'),('A1','$L/[N(L-N)]=1/N+1/(L-N)$.'),('M1','Integrate both sides.'),('A1',r'$\ln[N/(L-N)]=2kt+C$.'),('M1','Apply $N(0)=N_0$.'),('A1',r'$C=\ln[N_0/(L-N_0)]$.'),('A1',r'$2kt=\ln\dfrac{N(L-N_0)}{N_0(L-N)}$.')),p('e','Given $L=4N_0$ and $N(10)=3N_0$, find $k$.',2,('M1',r'$20k=\ln9$.'),('A1',r'$k=\ln3/10$.'))],sub='Differential equations')
add(139,'An implicit ellipse and its bounding rectangle',r'The ellipse $x^2-2xy+5y^2=16$ is enclosed by its smallest rectangle with sides parallel to the coordinate axes.',[p('a','Find $dy/dx$.',3,('M1','Differentiate implicitly.'),('A1',r'$2x-2y-2xy\prime+10yy\prime=0$.'),('A1',r'$y\prime=(x-y)/(x-5y)$.')),p('b','Find the horizontal and vertical tangent coordinates.',4,('A1','Horizontal tangents require $x=y$.'),('A1','Points $(2,2),(-2,-2)$.'),('A1','Vertical tangents require $x=5y$.'),('A1',r'Points $(2\sqrt5,2/\sqrt5),(-2\sqrt5,-2/\sqrt5)$.')),p('c','Find the upper and lower branches explicitly.',4,('M1','Solve the quadratic in $y$.'),('A1',r'$y=[2x\pm\sqrt{320-16x^2}]/10$.'),('A1',r'$y_\pm=x/5\pm(2/5)\sqrt{20-x^2}$.'),('A1',r'$-2\sqrt5\le x\le2\sqrt5$.')),p('d','Find the area of the ellipse above the $x$-axis.',3,('M1',r'Total area $=\int_{-\sqrt{20}}^{\sqrt{20}}(4/5)\sqrt{20-x^2}dx=8\pi$ using a semicircle.'),('R1',r'Rotation through $180^\circ$ about the origin swaps the parts above and below the axis.'),('A1',r'Area above $=4\pi$.')),p('e','Find the area inside the rectangle but outside the ellipse.',3,('M1',r'Rectangle width $4\sqrt5$, height $4$.'),('A1',r'Rectangle area $16\sqrt5$.'),('A1',r'Required area $16\sqrt5-8\pi$.'))],notes='Implicit derivatives, extrema and semicircle area checked; the half-area is justified by rotational symmetry.')
add(140,'A trigonometric family of polynomials',r'Let $f(x)=\cos(p\arccos(2x))$, $|x|<1/2$, where $p$ is real. You may use the recurrence $(1-4x^2)f^{(n+2)}=4(2n+1)xf^{(n+1)}+4(n^2-p^2)f^{(n)}$ for $n\ge0$.',[p('a',r'Find $f\prime(0)$.',2,('M1',r'$f\prime=2p\sin(p\arccos(2x))/\sqrt{1-4x^2}$.'),('A1',r'$f\prime(0)=2p\sin(p\pi/2)$.')),p('b','State $f(0)$.',1,('A1',r'$\cos(p\pi/2)$.')),p('c','Find the Maclaurin expansion through $x^4$.',5,('M1',r'At zero, $f^{(n+2)}(0)=4(n^2-p^2)f^{(n)}(0)$.'),('A1',r'$f\prime\prime(0)=-4p^2\cos(p\pi/2)$.'),('A1',r'$f^{(3)}(0)=8p(1-p^2)\sin(p\pi/2)$.'),('A1',r'$f^{(4)}(0)=-16p^2(4-p^2)\cos(p\pi/2)$.'),('A1',r'$f=\cos(p\pi/2)+2p\sin(p\pi/2)x-2p^2\cos(p\pi/2)x^2+\tfrac43p(1-p^2)\sin(p\pi/2)x^3-\tfrac23p^2(4-p^2)\cos(p\pi/2)x^4+O(x^5)$.')),p('d',r'For odd integer $p$, find $\lim_{x\to0}f(x)/x$.',3,('A1',r'$\cos(p\pi/2)=0$.'),('M1','Divide the series by $x$.'),('A1',r'Limit $=2p\sin(p\pi/2)$.')),p('e','For positive integer $p$, show that $f$ is a polynomial of degree $p$.',4,('R1','For even $p$, every odd derivative at zero vanishes; for odd $p$, every even derivative does.'),('A1','The other parity’s recurrence reaches $n=p$, where its multiplier is zero.'),('R1','All subsequent derivatives in that parity vanish, while the coefficient of degree $p$ is non-zero because the earlier multipliers are non-zero.'),('R1','The analytic Maclaurin series therefore terminates at degree $p$.'))],sub='Maclaurin series',notes='Polynomial-degree claim is explicitly restricted to positive integers, correcting the ambiguity for negative integers.')
add(141,'An exponential-trigonometric curve',r'Let $f(x)=e^{-x}\cos x$ on $-\pi/2\le x\le\pi/2$.',[p('a',r'Find $f\prime$.',2,('M1','Use the product rule.'),('A1',r'$f\prime=-e^{-x}(\cos x+\sin x)$.')),p('b',r'Find $f\prime\prime$.',2,('M1','Differentiate and simplify.'),('A1',r'$f\prime\prime=2e^{-x}\sin x$.')),p('c','Find and classify the stationary point.',4,('M1',r'$\cos x+\sin x=0$.'),('A1',r'$x=-\pi/4$.'),('A1',r'$y=e^{\pi/4}/\sqrt2$.'),('R1',r'$f\prime\prime<0$ there, so it is a maximum.')),p('d','Find and justify the inflexion point.',2,('A1','$(0,1)$.'),('R1',r'$f\prime\prime$ changes from negative to positive at zero.')),p('e','Sketch the curve with its key points.',3,('A1',r'Endpoints $(-\pi/2,0),(\pi/2,0)$.'),('A1','Maximum and inflexion correctly labelled.'),('A1','Positive curve with the monotonicity and concavity found above.')),p('f','Find the area between the curve and the $x$-axis exactly.',6,('M1',r'Let $I=\int e^{-x}\cos x\,dx$ and integrate by parts.'),('A1',r'$I=-e^{-x}\cos x-\int e^{-x}\sin x\,dx$.'),('M1','Integrate the remaining integral by parts again and solve for $I$.'),('A1',r'$I=\tfrac12e^{-x}(-\cos x+\sin x)+C$.'),('M1',r'Evaluate from $-\pi/2$ to $\pi/2$; the curve is non-negative.'),('A1',r'Area $=(e^{\pi/2}+e^{-\pi/2})/2$.')),p('g',r'The curvature is $\kappa=|f\prime\prime|/[1+(f\prime)^2]^{3/2}$. Find it at the maximum.',3,('A1',r'$f\prime=0$ there.'),('M1',r'$\kappa=|2e^{\pi/4}\sin(-\pi/4)|$.'),('A1',r'$\kappa=\sqrt2e^{\pi/4}$.')),p('h','Find the curvature at the inflexion point and explain.',2,('A1',r'$\kappa=0$.'),('R1',r'At $x=0$, $f\prime\prime=0$ while the denominator is positive.'))])
add(142,'Linear equation with a trigonometric substitution',r'For $0<x<4/3$, solve $xy\prime=6x/(16-9x^2)^{3/2}-2y$.',[p('a','Find an integrating factor after writing the equation in standard form.',3,('A1',r'$y\prime+2y/x=6/(16-9x^2)^{3/2}$.'),('M1',r'$\mu=e^{\int2/x\,dx}$.'),('A1',r'$\mu=x^2$.')),p('b',r'Use $x=(4/3)\sin\theta$ to find the general solution.',8,('M1',r'$(x^2y)\prime=6x^2/(16-9x^2)^{3/2}$.'),('A1',r'$dx=(4/3)\cos\theta\,d\theta$, $\sqrt{16-9x^2}=4\cos\theta$.'),('A1',r'The integral becomes $(2/9)\int\tan^2\theta\,d\theta$.'),('M1',r'Use $\tan^2\theta=\sec^2\theta-1$.'),('A1',r'$x^2y=(2/9)(\tan\theta-\theta)+C$.'),('A1',r'$\tan\theta=3x/\sqrt{16-9x^2}$.'),('A1',r'$\theta=\arcsin(3x/4)$.'),('A1',r'$y=\dfrac2{3x\sqrt{16-9x^2}}-\dfrac2{9x^2}\arcsin(3x/4)+\dfrac C{x^2}$.'))],sub='Differential equations')
add(143,'Induction for a radical derivative',r'Let $f(x)=(1-2x)^{-1/2}$, $x<1/2$.',[p('a',r'Find $f\prime\prime$.',3,('M1','Apply the chain rule.'),('A1',r'$f\prime=(1-2x)^{-3/2}$.'),('A1',r'$f\prime\prime=3(1-2x)^{-5/2}$.')),p('b',r'Prove that $f^{(n)}=\dfrac{(2n)!}{2^n n!}(1-2x)^{-n-1/2}$ for every $n\ge0$.',9,('A1','At $n=0$, the coefficient is $1$ and the expression is $f$.'),('M1','Assume the formula for $n=k$.'),('M1','Differentiate using the chain rule.'),('A1',r'New multiplier $(-k-1/2)(-2)=2k+1$.'),('A1',r'New exponent $-k-3/2$.'),('M1','Rewrite the coefficient in factorial form.'),('A1',r'$\dfrac{(2k)!(2k+1)}{2^k k!}=\dfrac{(2k+2)!}{2^{k+1}(k+1)!}$.'),('A1','The exponent is $-(k+1)-1/2$.'),('R1','Thus the formula holds for $k+1$ and hence for all non-negative integers.')),p('c',r'The coefficient of $x^2$ in $f(x)\cos(mx)$ is $-3$. Find all real values of $m$.',9,('A1','$f(0)=1$.'),('A1',r'$f\prime(0)=1$.'),('A1',r'$f\prime\prime(0)=3$.'),('M1','Use the Maclaurin formula through degree two.'),('A1',r'$f=1+x+\tfrac32x^2+O(x^3)$.'),('A1',r'$\cos(mx)=1-m^2x^2/2+O(x^4)$.'),('M1','Multiply and collect the degree-two terms.'),('A1','$3/2-m^2/2=-3$, so $m^2=9$.'),('A1','$m=3$ or $m=-3$.'))],sub='Maclaurin series')
add(144,'An exponential of inverse tangent',r'Let $f(x)=e^{2\arctan x}$.',[p('a',r'Find $f\prime$ and $f\prime\prime$ in terms of $f$.',6,('M1','Use the chain rule.'),('A1',r'$f\prime=2f/(1+x^2)$.'),('M1','Differentiate using the quotient rule.'),('A1',r'$f\prime\prime=[2f\prime(1+x^2)-4xf]/(1+x^2)^2$.'),('M1',r'Substitute for $f\prime$.'),('A1',r'$f\prime\prime=4(1-x)f/(1+x^2)^2$.')),p('b','Find the Maclaurin expansion through $x^3$.',6,('A1','$f(0)=1$.'),('A1',r'$f\prime(0)=2$, $f\prime\prime(0)=4$.'),('M1',r'Differentiate the expression for $f\prime\prime$.'),('A1','At zero, the prefactor $4(1-x)/(1+x^2)^2$ has derivative $-4$.'),('A1',r'$f^{(3)}(0)=(-4)(1)+4(2)=4$.'),('A1',r'$f=1+2x+2x^2+\tfrac23x^3+O(x^4)$.')),p('c',r'Find the Maclaurin expansion of $\sin(\ln(1+3x))$ through $x^3$.',6,('M1','Expand the logarithm first.'),('A1',r'$u=3x-\tfrac92x^2+9x^3+O(x^4)$.'),('A1',r'$\sin u=u-u^3/6+O(u^5)$.'),('M1','Only $(3x)^3$ is needed from $u^3$ at this order.'),('A1',r'The cubic coefficient is $9-27/6=9/2$.'),('A1',r'$3x-\tfrac92x^2+\tfrac92x^3+O(x^4)$.')),p('d',r'Find $\lim_{x\to0}[f(x)-1]/\sin(\ln(1+3x))$.',2,('M1','Compare the leading linear terms.'),('A1','$2/3$.'))],sub='Maclaurin series')
add(145,'Reduction formula and volume',r'Let $f(x)=2x(\ln x)^2$, $x>0$. Region R lies between the curve and the $x$-axis from $x=1$ to $x=e$. Define $I_n=\int_1^e x^2(\ln x)^n dx$.',[p('a','State the $x$-intercept.',1,('A1','$(1,0)$.')),p('b','Find the area of R exactly.',5,('M1',r'Integrate $2x(\ln x)^2$ by parts with $u=(\ln x)^2$, $dv=2x\,dx$.'),('A1',r'Integral $=x^2(\ln x)^2-\int2x\ln x\,dx$.'),('M1','Apply integration by parts again.'),('A1',r'Primitive $x^2(\ln x)^2-x^2\ln x+x^2/2$.'),('A1','Area $(e^2-1)/2$.')),p('c','Find $I_0$, derive a recurrence, and use it to find $I_1,I_2,I_3$.',7,('A1','$I_0=(e^3-1)/3$.'),('M1',r'For $n\ge1$, use $u=(\ln x)^n$, $dv=x^2dx$.'),('A1',r'$I_n=[x^3(\ln x)^n/3]_1^e-(n/3)I_{n-1}$.'),('A1','$I_n=(e^3-nI_{n-1})/3$.'),('A1','$I_1=(2e^3+1)/9$.'),('A1','$I_2=(5e^3-2)/27$.'),('A1','$I_3=(4e^3+2)/27$.')),p('d','Find the volume formed by revolving R about the $x$-axis.',5,('M1',r'$V=\pi\int_1^e[2x(\ln x)^2]^2dx$.'),('A1',r'$V=4\pi I_4$.'),('M1','Apply the recurrence once more.'),('A1','$I_4=(11e^3-8)/81$.'),('A1',r'$V=4\pi(11e^3-8)/81$.'))],sub='Integration by parts')
