add(146,'Two population growth models',r'A fish population initially contains $3600$ fish and is modelled by $dP/dt=k\sqrt P$, where $t$ is in weeks. It doubles after $20$ weeks.',[p('a','Find $P(t)$ and the exact value of $k$.',4,('M1',r'$2\sqrt P=kt+C$.'),('A1','$C=120$, so $P=(60+kt/2)^2$.'),('M1',r'$\sqrt{7200}=60+10k$.'),('A1',r'$k=6(\sqrt2-1)$.')),p('b','Estimate the population after $30$ weeks to the nearest fish.',2,('M1',r'$P(30)=[60+90(\sqrt2-1)]^2$.'),('A1',rf'${round(float(P.subs(t,30)))}$ fish.')),p('c','State one limitation of this model for long times.',2,('A1','It predicts unbounded population growth.'),('R1','A finite habitat has limited food and space, so such growth cannot continue indefinitely.')),p('d',r'A refined model obeys $P_2\prime=[2.5+4\cos(0.3\pi t)]\sqrt{P_2}$ and $P_2(0)=3600$. Find $P_2(t)$.',5,('M1',r'$dP_2/\sqrt{P_2}=[2.5+4\cos(0.3\pi t)]dt$.'),('A1',r'$2\sqrt{P_2}=2.5t+\frac{40}{3\pi}\sin(0.3\pi t)+C$.'),('M1','Use the initial population.'),('A1','$C=120$.'),('A1',r'$P_2=[60+1.25t+\frac{20}{3\pi}\sin(0.3\pi t)]^2$.')),p('e',r'Sketch both models on $0\le t\le50$, identifying their main differences.',3,('A1','Both start at $(0,3600)$.'),('A1',rf'The first increases convexly to $P(50)={num(P.subs(t,50))}$.'),('A1',rf'The refined curve oscillates about an increasing trend, with periods of decline; $P_2(50)={num(P2.subs(t,50))}$.')),p('f','Under the refined model, at the end of which first whole week is the population at least $6000$?',2,('M1','Check the refined model at successive integer weeks (or locate its first crossing and check nearby integers).'),('A1',rf'Week ${week}$: $P_2({week-1})={num(P2.subs(t,week-1))}<6000$, $P_2({week})={num(P2.subs(t,week))}\ge6000$.'))],True,'Differential equations',notes='Both initial conditions and differential equations checked symbolically; first whole-week threshold found by direct integer scan.')
k=S.Rational(25,8)*(2**S.Rational(2,3)-1);M=(25+S.Rational(2,3)*k*t)**S.Rational(3,2);M2=(25+S.Rational(4,3)*t+12/S.pi*(1-S.cos(S.pi*t/6)))**S.Rational(3,2);hour=next(j for j in range(41) if float(M2.subs(t,j))>=350)
add(147,'Mass growth with an oscillating rate',r'A biological culture initially has mass $125$ kg. Its first model is $dM/dt=kM^{1/3}$, with $t$ in hours. The mass doubles after $12$ hours.',[p('a','Find $M(t)$ and $k$ exactly.',4,('M1',r'$\tfrac32M^{2/3}=kt+C$.'),('A1',r'$M=[25+(2k/3)t]^{3/2}$ from $M(0)=125$.'),('M1','$250^{2/3}=25+8k$.'),('A1',r'$k=\tfrac{25}{8}(2^{2/3}-1)$.')),p('b','Find the mass after $18$ hours to the nearest kilogram.',2,('M1','Substitute $t=18$ in the exact solution.'),('A1',rf'${round(float(M.subs(t,18)))}$ kg.')),p('c','State a limitation of the model.',2,('A1','It assumes the same rate law continues indefinitely without a resource limit.'),('R1','Available nutrients and space would eventually constrain the growth.')),p('d',r'A refined model is $M_2\prime=[2+3\sin(\pi t/6)]M_2^{1/3}$, with $M_2(0)=125$. Find $M_2(t)$.',5,('M1',r'$M_2^{-1/3}dM_2=[2+3\sin(\pi t/6)]dt$.'),('A1',r'$\tfrac32M_2^{2/3}=2t-(18/\pi)\cos(\pi t/6)+C$.'),('M1','Use the initial mass.'),('A1',r'$C=75/2+18/\pi$.'),('A1',r'$M_2=[25+\tfrac43t+\tfrac{12}{\pi}(1-\cos(\pi t/6))]^{3/2}$.')),p('e',r'Sketch both models for $0\le t\le40$.',3,('A1','Both begin at $(0,125)$.'),('A1',rf'The first grows smoothly and convexly to $M(40)={num(M.subs(t,40))}$.'),('A1',rf'The refined model has a rising trend with intervals of decline; $M_2(40)={num(M2.subs(t,40))}$.')),p('f','Under the refined model, at the end of which first whole hour is the mass at least $350$ kg?',2,('M1','Evaluate the model at integer hours, checking the first threshold attainment.'),('A1',rf'Hour ${hour}$: $M_2({hour-1})={num(M2.subs(t,hour-1))}<350$, $M_2({hour})={num(M2.subs(t,hour))}\ge350$.'))],True,'Differential equations',notes='The integration constant includes the cosine initial value; this corrects an initial-condition inconsistency in the reference solution model. Both equations and threshold scans verified.')
save()
# Explicit independent residual checks for the advanced, manually written solutions.
def zero(expr,label):
 result=S.simplify(S.trigsimp(expr))
 assert result==0,(label,result)
 checks.append(label)
xx=S.symbols('X',positive=True)
for n,sol,rhs,point,target in [
 (100,(x+2)/(1-2*x),(1+y*y)/(1+x*x),0,2),
 (101,(x**3/3+3*x*x/2+3)/(x+3),x-y/(x+3),0,1),
 (107,S.Rational(1,2)+S.Rational(5,2)*S.exp(-2*x*x),2*x-4*x*y,0,3),
 (119,x*(2*x/3-2)/(3-2*x/3),2+6*y/x+3*y*y/x**2,3,0),
 (121,x*(3+S.Rational(2,3)*S.log(x)),y/x+S.Rational(2,3),1,3),
 (127,x/8+S.Rational(1,16)-S.Rational(5,16)*S.exp(2*x-4),2*y-x/4,2,0),
 (128,S.Rational(2,3)*(1+x**6)+4/(3*S.sqrt(1+x**6)),6*x**5-3*x**5*y/(1+x**6),0,2),
 (133,x*(9*x-8)/(4-3*x),6+6*y/x+y*y/x**2,1,1)]:
 zero(S.diff(sol,x)-rhs.subs(y,sol),f'Q{n}:ODE residual');zero(sol.subs(x,point)-target,f'Q{n}:initial condition')
pp=S.symbols('p',integer=True,positive=True);sol=2*(x**(pp+1)+(pp+1)/x)/(pp+2)
zero(x*S.diff(sol,x)+sol-2*x**(pp+1),'Q134:parameter ODE');zero(sol.subs(x,1)-2,'Q134:initial condition')
sol=2/(3*xx*S.sqrt(16-9*xx**2))-2*S.asin(3*xx/4)/(9*xx**2)
zero(xx*S.diff(sol,xx)+2*sol-6*xx/(16-9*xx**2)**S.Rational(3,2),'Q142:ODE residual')
for n,func,expected,order in [
 (102,S.cos(3*x)*S.cos(6*x)*S.cos(12*x),1-S.Rational(189,2)*x*x,3),
 (106,S.exp(2*x)*S.cos(2*x),1+2*x-S.Rational(8,3)*x**3-S.Rational(8,3)*x**4,5),
 (107,S.Rational(1,2)+S.Rational(5,2)*S.exp(-2*x*x),3-5*x*x+5*x**4,5),
 (114,3*(1-x)*S.log(1-x)+3*x,S.Rational(3,2)*x*x+x**3/2+x**4/4+S.Rational(3,20)*x**5+x**6/10,7),
 (115,S.exp(-3*x)/(1+3*x),1-6*x+S.Rational(45,2)*x*x,3),
 (122,S.exp(2*x)*S.cos(2*x),1+2*x-S.Rational(8,3)*x**3-S.Rational(8,3)*x**4-S.Rational(16,15)*x**5,6),
 (131,S.acos(2*x)**2,S.pi**2/4-2*S.pi*x+4*x*x-S.Rational(4,3)*S.pi*x**3+S.Rational(16,3)*x**4,5),
 (143,(1-2*x)**-S.Rational(1,2),1+x+S.Rational(3,2)*x*x,3),
 (144,S.exp(2*S.atan(x)),1+2*x+2*x*x+S.Rational(2,3)*x**3,4),
 (144,S.sin(S.log(1+3*x)),3*x-S.Rational(9,2)*x*x+S.Rational(9,2)*x**3,4)]:
 zero(S.series(func,x,0,order).removeO()-expected,f'Q{n}:series')
for n,F,integrand in [
 (97,x*S.acos(2*x)-S.sqrt(1-4*x*x)/2,S.acos(2*x)),
 (99,S.atan((S.exp(x)-3)/2)/2,S.exp(x)/(S.exp(2*x)-6*S.exp(x)+13)),
 (109,-2*S.cos(3*x)**4,24*S.sin(3*x)*S.cos(3*x)**3),
 (110,-S.Rational(2,3)*S.sqrt(1-3*x)+S.Rational(2,9)*(1-3*x)**S.Rational(3,2),3*x/S.sqrt(1-3*x)),
 (113,S.atan(S.tan(x)/S.sqrt(5))/S.sqrt(5),1/(3+2*S.cos(2*x))),
 (118,-(6*x*x+3)*S.exp(-2*x*x),24*x**3*S.exp(-2*x*x)),
 (135,x*S.tan(x)+S.log(-S.cos(x)),x/S.cos(x)**2),
 (137,S.cos(3*x)**3/9-S.cos(3*x)/3,S.sin(3*x)**3),
 (141,S.exp(-x)*(-S.cos(x)+S.sin(x))/2,S.exp(-x)*S.cos(x)),
 (145,x*x*S.log(x)**2-x*x*S.log(x)+x*x/2,2*x*S.log(x)**2)]:
 zero(S.diff(F,x)-integrand,f'Q{n}:primitive residual')
zero(S.integrate(1/(x*x+4)**2,(x,0,2))-(S.pi+2)/64,'Q104:definite integral')
zero(S.pi*S.integrate(1/(4*y*y+16),(y,0,2*S.sqrt(3)))-S.pi**2/24,'Q108:volume')
zero(S.integrate(x**4*S.exp(-2*x),(x,0,S.oo))-S.Rational(3,4),'Q129:improper integral')
zero(S.integrate(x*x*S.log(x)**4,(x,1,S.E))-(11*S.E**3-8)/81,'Q145:reduction value')
# Differential equations for nonnegative masses are most directly checked before raising to powers.
baseP=60+S.Rational(5,4)*t+S.Rational(20,3)/S.pi*S.sin(3*S.pi*t/10)
zero(2*S.diff(baseP,t)-(S.Rational(5,2)+4*S.cos(3*S.pi*t/10)),'Q146:refined ODE');zero(baseP.subs(t,0)**2-3600,'Q146:initial condition')
baseM=25+S.Rational(4,3)*t+12/S.pi*(1-S.cos(S.pi*t/6))
zero(S.Rational(3,2)*S.diff(baseM,t)-(2+3*S.sin(S.pi*t/6)),'Q147:refined ODE');zero(baseM.subs(t,0)**S.Rational(3,2)-125,'Q147:initial condition')
assert float(baseP.subs(t,0))-20/(3*math.pi)>0
assert len(Q)==147 and set(Q)==set(range(1,148))
